node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Get product info
const product = db.prepare(\"SELECT * FROM products WHERE product_id = 'PROD-2028EE'\").all();
console.log('Product:', JSON.stringify(product, null, 2));

// Get schema for rt_variants
const schema = db.prepare(\"SELECT sql FROM sqlite_master WHERE name = 'rt_variants'\").get();
console.log('Variants schema:', schema.sql);

// Get variants for this product
const variants = db.prepare(\"SELECT * FROM rt_variants WHERE product_id = 'PROD-2028EE'\").all();
console.log('Variants:', JSON.stringify(variants, null, 2));
"

node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Check if any other products reference PROD-2028EE in their compatible_with_json
const compatible = db.prepare(\"SELECT product_id, name, compatible_with_json FROM products WHERE compatible_with_json LIKE '%PROD-2028EE%'\").all();
console.log('Products referencing PROD-2028EE in compatibility:', JSON.stringify(compatible, null, 2));

// Also show the full specs and description again for any compatibility notes
const product = db.prepare(\"SELECT specs_json, compatible_with_json, description FROM products WHERE product_id = 'PROD-2028EE'\").get();
console.log('Specs:', product.specs_json);
console.log('Compatible with:', product.compatible_with_json);
console.log('Description:', product.description);
"
